import java.util.*;

public class Main {
    static final int MAXN = 2002;
    static final int INF = (int)1e9;
    static int[][] capacity = new int[MAXN][MAXN];
    static List<Integer>[] adj = new ArrayList[MAXN];
    static boolean[] visited = new boolean[MAXN];
    static int[] parent = new int[MAXN];

    static int[][] directions = { {1,0}, {0,1}, {-1,0}, {0,-1} };

    static int findFlow(int u) {
        if (u == 1) return INF;
        visited[u] = true;
        for (int v : adj[u]) {
            if (!visited[v] && capacity[u][v] > 0) {
                int flow = findFlow(v);
                if (flow > 0) {
                    parent[v] = u;
                    return Math.min(flow, capacity[u][v]);
                }
            }
        }
        return 0;
    }

    static int computeFlow() {
        int totalFlow = 0;
        while (true) {
            Arrays.fill(visited, false);
            int flow = findFlow(0);
            if (flow == 0) break;
            totalFlow += flow;
            int v = 1;
            while (v != 0) {
                int u = parent[v];
                capacity[u][v] -= flow;
                capacity[v][u] += flow;
                v = u;
            }
        }
        return totalFlow;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        for (int i = 0; i < MAXN; i++) {
            adj[i] = new ArrayList<>();
        }
        int size = sc.nextInt();
        int timeLimit = sc.nextInt();

        String[] sci = new String[size];
        String[] capLab = new String[size];

        int[][] vert = new int[size][size][2];
        int malfunctionIdx = -1;

        int N = 2;
        for (int i = 0; i < size; i++) {
            sci[i] = sc.next();
            for (int j = 0; j < size; j++) {
                if (sci[i].charAt(j) >= '1' && sci[i].charAt(j) <= '9') {
                    capacity[0][N] = sci[i].charAt(j) - '0';
                    adj[0].add(N);
                    adj[N].add(0);
                    vert[i][j][0] = N++;
                } else if (sci[i].charAt(j) == 'Z') {
                    malfunctionIdx = 100 * i + j;
                    // Replace 'Z' with 'Y' as in original code
                    StringBuilder sb = new StringBuilder(sci[i]);
                    sb.setCharAt(j, 'Y');
                    sci[i] = sb.toString();
                }
            }
        }

        int M = N;
        for (int i = 0; i < size; i++) {
            capLab[i] = sc.next();
            for (int j = 0; j < size; j++) {
                if (capLab[i].charAt(j) >= '1' && capLab[i].charAt(j) <= '9') {
                    capacity[M][1] = capLab[i].charAt(j) - '0';
                    adj[M].add(1);
                    adj[1].add(M);
                    vert[i][j][1] = M++;
                }
            }
        }

        int[][] die = new int[size][size];
        for (int i = 0; i < size; i++) {
            Arrays.fill(die[i], timeLimit + 1);
        }
        die[malfunctionIdx / 100][malfunctionIdx % 100] = 0;

        Queue<Integer> q = new LinkedList<>();
        q.offer(malfunctionIdx);
        while (!q.isEmpty()) {
            int x = q.poll();
            int y = x % 100;
            x /= 100;
            for (int[] d : directions) {
                int nx = x + d[0];
                int ny = y + d[1];
                if (nx >= 0 && nx < size && ny >= 0 && ny < size && sci[nx].charAt(ny) != 'Y' && die[nx][ny] > die[x][y] + 1) {
                    die[nx][ny] = die[x][y] + 1;
                    q.offer(100 * nx + ny);
                }
            }
        }

        int[][] reach = new int[size][size];
        for (int i = 0; i < size; i++) {
            Arrays.fill(reach[i], timeLimit + 1);
        }

        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (sci[i].charAt(j) >= '1' && sci[i].charAt(j) <= '9') {
                    for (int x = 0; x < size; x++) {
                        Arrays.fill(reach[x], timeLimit + 1);
                    }
                    reach[i][j] = 0;
                    if (capLab[i].charAt(j) >= '1' && capLab[i].charAt(j) <= '9') {
                        capacity[vert[i][j][0]][vert[i][j][1]] = INF;
                        adj[vert[i][j][0]].add(vert[i][j][1]);
                        adj[vert[i][j][1]].add(vert[i][j][0]);
                    }
                    Queue<Integer> q2 = new LinkedList<>();
                    q2.offer(100 * i + j);
